&L=e^{\gamma t}\Big(\tfrac12 m\dot q^{\,2}-\tfrac12 kq^2\Big)
\;\Rightarrow\;
m\ddot q+m\gamma\dot q+kq=0
\quad(\text{damped oscillator}),\\[4pt]
&\text{No ordinary energy conservation since } \partial L/\partial t\neq 0,\;
H=e^{\gamma t}\Big(\tfrac12 m\dot q^{\,2}+\tfrac12 kq^2\Big)\not=\text{const},\\[4pt]
&S=e^{\gamma t/2}q:\;
L(S,\dot S)=\tfrac12 m\Big(\dot S-\tfrac{\gamma}{2}S\Big)^2-\tfrac12 kS^2
\simeq \tfrac12 m\dot S^{\,2}-\tfrac12\Big(k-\tfrac{m\gamma^2}{4}\Big)S^2,\\[4pt]
&\Rightarrow\;
m\ddot S+\Big(k-\tfrac{m\gamma^2}{4}\Big)S=0,\quad
E_S=\tfrac12 m\dot S^{\,2}+\tfrac12\Big(k-\tfrac{m\gamma^2}{4}\Big)S^2=\text{const},\\[4pt]
&\text{Pulled back invariant: }\;
I=e^{\gamma t}\Big(\tfrac12 m\dot q^{\,2}+\tfrac{m\gamma}{2}q\dot q+\tfrac12 kq^2\Big)=\text{const},\\[4pt]
&\text{Solutions related by } q(t)=e^{-\gamma t/2}S(t)\;
(\text{so }q\text{ is }S\text{ with an exponential decay envelope}).
\end{aligned}

