&\text{(a) } \dot{\mathbf L}=\mathbf r\times\mathbf F=\mathbf 0\ \Rightarrow\ \mathbf L=\text{const},\ \mathbf r(t)\ \text{lies in the fixed plane }\perp\mathbf L.\\[4pt]
&\text{(b) With }\omega=\sqrt{K/m}:\quad x(t)=a\cos(\omega t),\quad y(t)=\frac{V}{\omega}\sin(\omega t),\quad z(t)=0.\\[4pt]
&\text{(c) Orbit: }\ \frac{x^2}{a^2}+\frac{y^2}{(V/\omega)^2}=1\ \text{(ellipse centered at the origin).}\\[4pt]
&\text{(d) Period: }\ T=\frac{2\pi}{\omega}=2\pi\sqrt{\frac{m}{K}}.\\[4pt]
&\text{(e) Kepler laws: equal areas holds (central force), but 1st and 3rd laws do not (origin is not a focus; }T\text{ independent of size).}
\end{aligned}

