&k\to 0:\; x\to v_0\cos\theta\,t,\; y\to v_0\sin\theta\,t-\tfrac12 gt^2,\\
&\alpha=1+\dfrac{k v_0\sin\theta}{g},\quad
T=\dfrac{\alpha+W_0\!\left(-\alpha e^{-\alpha}\right)}{k},\\
&R \approx \dfrac{v_0^2\sin(2\theta)}{g}
-\dfrac{8}{3}\,\dfrac{6\pi\eta R}{m}\,\dfrac{v_0^3\cos\theta\,\sin^2\theta}{g^2}
=\dfrac{v_0^2\sin(2\theta)}{g}\left[1-\dfrac{4}{3}\dfrac{6\pi\eta R\, v_0\sin\theta}{m g}\right].
\end{aligned}

